const body = $json.body || $json;
const channel = String(body.channel || 'webhook').trim();
const senderId = String(body.sender_id || '').trim();
const contentId = String(body.content_id || '').trim();
const message = String(body.message || '').trim();
if (!senderId || !/^CONTENT-\d{4}-\d{5}$/.test(contentId) || !message) throw new Error('Payload invalido: sender_id, content_id e message sao obrigatorios.');
const externalMessageId = String(body.external_message_id || ('approval-' + Date.now() + '-' + Math.random().toString(36).slice(2,10)));
return [{json:{channel,sender_id:senderId,content_id:contentId,message,external_message_id:externalMessageId}}];

const input=$json;
const original=String(input.message);
const text=original.toLocaleLowerCase('pt-BR');
let decision='unclear',changes=[],regen=false,clarification='Pode me dizer o que você gostaria de alterar?';
if(/(rejeito|não quero usar|nao quero usar|descarto essa arte)/.test(text)){decision='rejected';clarification=null;}
else if(/(troca|substitui).*(imagem|produto)|outra foto|nova imagem/.test(text)){decision='changes_requested';regen=true;clarification=null;}
else{
 if(/deixa.*(imagem|produto).*(maior|grande)|aumenta.*(imagem|produto)/.test(text))changes.push({target:'product_image',operation:'scale',value:1.15});
 if(/move.*logo.*(cima|acima)/.test(text))changes.push({target:'logo',operation:'move',value:{direction:'up',amount:20}});
 const exact=original.match(/(?:troca|mude|altera)(?: o)? (?:t[ií]tulo|headline) para\s+(.+?)[.!]?$/i);
 if(exact)changes.push({target:'headline',operation:'replace_text',value:exact[1].replace(/[.!]+$/,'').trim()});
 if(changes.length){decision='changes_requested';clarification=null;}
 else if(/(pode postar|est[aá] aprovado|aprovado|pode seguir|ficou [oó]timo|perfeito)/.test(text)){decision='approved';clarification=null;}
}
const structured={decision,confidence:1,requires_image_regeneration:regen,changes,clarification_message:clarification};
return [{json:{...input,structured_decision:structured,interpretation_provider:'mock',interpretation_model:'mock-approval-v2',interpretation_response_id:'mock-'+Date.now(),interpretation_usage:{input_tokens:0,output_tokens:0,total_tokens:0},interpretation_cost:0,interpretation_prompt:input.message}}];

const input=$json;
const moveValue={type:'object',additionalProperties:false,required:['direction','amount'],properties:{direction:{type:'string',enum:['up','down','left','right']},amount:{type:'number',minimum:1,maximum:120}}};
const schema={type:'object',additionalProperties:false,required:['decision','confidence','requires_image_regeneration','changes','clarification_message'],properties:{decision:{type:'string',enum:['approved','changes_requested','rejected','unclear']},confidence:{type:'number',minimum:0,maximum:1},requires_image_regeneration:{type:'boolean'},changes:{type:'array',maxItems:8,items:{type:'object',additionalProperties:false,required:['target','operation','value'],properties:{target:{type:'string',enum:['product_image','headline','subtitle','cta','logo','background']},operation:{type:'string',enum:['scale','move','replace_text','change_color']},value:{anyOf:[{type:'number'},{type:'string'},moveValue]}}}},clarification_message:{type:['string','null']}}};
const instructions='Classifique a resposta de aprovacao em portugues e produza somente JSON estrito. Nunca gere codigo, comandos, coordenadas ou caminhos. approved exige aprovacao inequivoca. rejected exige rejeicao inequivoca e sem pedido concreto. unclear significa insatisfacao sem alteracao acionavel. Troca de produto/foto/composicao exige requires_image_regeneration=true. scale: apenas product_image/logo, numero entre 0.70 e 1.40. move: product_image/headline/subtitle/cta/logo, value={direction:up|down|left|right,amount:1..120}. replace_text: headline/subtitle/cta e preserve literalmente o texto fornecido. change_color: somente background/headline/subtitle/cta e apenas cor da brand_palette.';
const prompt=JSON.stringify({message:input.message,current_version:input.version_label,layout:{product_image:input.layout_spec.product_image,headline:input.layout_spec.headline,subtitle:input.layout_spec.subtitle,cta:input.layout_spec.cta,logo:input.layout_spec.logo,background:input.layout_spec.background},brand_palette:input.palette});
const model=!input.approval_model||input.approval_model==='mock-v1'?'gpt-5-mini':input.approval_model;
return [{json:{...input,interpretation_prompt:prompt,openai_request:{model,store:false,instructions,input:prompt,text:{format:{type:'json_schema',name:'approval_decision',strict:true,schema},verbosity:'low'}}}}];

const response=$json;
const context=$('Montar Requisicao Aprovacao').first().json;
const text=response.output_text||(response.output||[]).flatMap(i=>i.content||[]).find(i=>i.type==='output_text')?.text;
if(!text) throw new Error('OpenAI nao retornou approval Structured Output.');
const usage=response.usage||{};
const inputTokens=Number(usage.input_tokens||0), cached=Number(usage.input_tokens_details?.cached_tokens||0), output=Number(usage.output_tokens||0);
const cost=((inputTokens-cached)*0.25+cached*0.025+output*2)/1000000;
return [{json:{...context,structured_decision:JSON.parse(text),interpretation_provider:'openai',interpretation_model:response.model||context.approval_model,interpretation_response_id:response.id,interpretation_usage:usage,interpretation_cost:cost}}];

const input=$json;
const d=input.structured_decision||{};
const decisions=['approved','changes_requested','rejected','unclear'];
const targets=['product_image','headline','subtitle','cta','logo','background'];
const operations=['scale','move','replace_text','change_color'];
if(!decisions.includes(d.decision)||typeof d.confidence!=='number'||!Array.isArray(d.changes)||typeof d.requires_image_regeneration!=='boolean')throw new Error('Structured decision invalida.');
const message=String(input.message);
const explicitImageReplacement=/(troca|substitui).*(imagem|produto)|outra foto|nova imagem/i.test(message);
if(explicitImageReplacement)d.requires_image_regeneration=true;
let invalid=false;
for(const c of d.changes){
 if(!targets.includes(c.target)||!operations.includes(c.operation))invalid=true;
 if(c.operation==='scale'&&(!(typeof c.value==='number')||!['product_image','logo'].includes(c.target)))invalid=true;
 if(c.operation==='replace_text'&&(!(typeof c.value==='string')||!c.value.trim()||!['headline','subtitle','cta'].includes(c.target)))invalid=true;
 if(c.operation==='change_color'&&(!(typeof c.value==='string')||!['background','headline','subtitle','cta'].includes(c.target)||!input.palette.includes(c.value)))invalid=true;
 if(c.operation==='move'&&(!(c.value&&typeof c.value==='object')||!['product_image','headline','subtitle','cta','logo'].includes(c.target)||!['up','down','left','right'].includes(String(c.value.direction).toLowerCase())||typeof c.value.amount!=='number'||c.value.amount<=0||c.value.amount>120))invalid=true;
}
if(d.decision==='changes_requested'&&d.changes.length&&!explicitImageReplacement)d.requires_image_regeneration=false;
if(invalid||(d.decision==='changes_requested'&&!d.requires_image_regeneration&&!d.changes.length)){d.decision='unclear';d.changes=[];d.requires_image_regeneration=false;d.clarification_message='Pode me dizer com mais detalhes o que você gostaria de alterar?';}
if(['approved','rejected','unclear'].includes(d.decision)){d.changes=[];d.requires_image_regeneration=false;}
if(d.decision==='unclear')d.clarification_message=d.clarification_message||'Pode me dizer o que você gostaria de alterar?';
const automaticResponse=d.decision==='approved'?'Perfeito. Conteúdo aprovado e pronto para agendamento.':d.decision==='rejected'?'Entendido. Essa versão foi rejeitada. Se quiser, me diga o que gostaria de mudar para eu criar uma nova versão.':d.decision==='changes_requested'?(d.requires_image_regeneration?'A alteração pede uma nova fotografia. Registrei a solicitação e aguardarei autorização antes de gerar.':'Perfeito. Vou ajustar e preparar uma nova versão.'):(d.clarification_message||'Pode me dizer o que você gostaria de alterar?');
const outcomeEvent=d.decision==='approved'?'CONTENT_APPROVED':d.decision==='rejected'?'CONTENT_REJECTED':d.decision==='changes_requested'?(d.requires_image_regeneration?'IMAGE_REGENERATION_REQUIRED':'CHANGES_REQUESTED'):'CLARIFICATION_REQUESTED';
return [{json:{...input,structured_decision:d,automatic_response:automaticResponse,outcome_event:outcomeEvent}}];
